def handle(app, svc):
    resp = svc.apply(app) or {}
    decision = resp.get("decision")
    limit = resp.get("limit", 0) or 0

    # Network referral rule: self_employed with requested_limit > 6000
    # must go to manual review instead of being issued. A decline stays a decline.
    requested = app.get("requested_limit", 0) or 0
    if (app.get("employment") == "self_employed" and requested > 6000
            and decision == "approve"):
        return {"action": "queue_review", "limit": 0}

    if decision == "approve":
        return {"action": "issue", "limit": limit}
    if decision == "refer":
        return {"action": "queue_review", "limit": 0}
    # decline (default)
    return {"action": "decline", "limit": 0}

